// Capture the failure context from the Error Trigger.
const e = $input.first().json;
return [{ json: {
  workflow_id: e.workflow?.id ?? null,
  workflow_name: e.workflow?.name ?? null,
  execution_id: e.execution?.id ?? null,
  execution_url: e.execution?.url ?? null,
  failed_node: e.execution?.lastNodeExecuted ?? e.trigger?.error?.node?.name ?? null,
  error_message: e.execution?.error?.message ?? e.trigger?.error?.message ?? 'Unknown error',
  execution_mode: e.execution?.mode ?? null,
} }];
